#include <stdio.h>

static void sort_ascending(int sorted[], int length)
{
    for (int next = 0; next + 1 < length; ++next) {
        int least = next;
        for (int i = next + 1; i < length; ++i) {
            if (sorted[i] < sorted[least]) {
                least = i;
            }
        }
        int saved = sorted[next];
        sorted[next] = sorted[least];
        sorted[least] = saved;
    }
}

static void print_row(const int values[], int length)
{
    for (int i = 0; i < length; ++i) {
        if (i > 0) {
            putchar(' ');
        }
        printf("%d", values[i]);
    }
    putchar('\n');
}

int main(void)
{
    int readings[] = {4, 1, 4, 2};
    const int length = (int)(sizeof readings / sizeof readings[0]);
    sort_ascending(readings, length);
    print_row(readings, length);
    return 0;
}

