#include <ctype.h>
#include <errno.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>

enum { READ_BAD = -1, READ_END = 0, READ_OK = 1 };

/* Read one complete line. Drain an invalid line to its newline or EOF. */
static int read_line(char line[], size_t cap)
{
    size_t used = 0;
    int ch;
    int rejected = 0;
    while ((ch = getchar()) != EOF && ch != '\n') {
        if (ch == '\0' || ch > CHAR_MAX || used == cap - 1) {
            rejected = 1;
        } else {
            line[used++] = (char)ch;
        }
    }

    if (ferror(stdin) || rejected) {
        return READ_BAD;
    }
    if (ch == EOF && used == 0) {
        return READ_END;
    }
    line[used] = '\0';
    return READ_OK;
}

static int read_integer(int low, int high, int *out)
{
    char line[64];
    int state = read_line(line, sizeof line);
    if (state != READ_OK) {
        return state;
    }

    char *end;
    errno = 0;
    long value = strtol(line, &end, 10);
    if (end == line || errno == ERANGE || value < low || value > high) {
        return READ_BAD;
    }
    while (isspace((unsigned char)*end)) {
        ++end;
    }
    if (*end != '\0') {
        return READ_BAD;
    }

    *out = (int)value;
    return READ_OK;
}

static void sort_ascending(int sorted[], int length)
{
    for (int next = 0; next + 1 < length; ++next) {
        int least = next;
        for (int i = next + 1; i < length; ++i) {
            if (sorted[i] > sorted[least]) /* TODO: choose the smallest. */ {
                least = i;
            }
        }
        int saved = sorted[next];
        sorted[next] = sorted[least];
        sorted[least] = saved;
    }
}

static void print_row(const int values[], int length)
{
    for (int i = 0; i < length; ++i) {
        if (i > 0) {
            putchar(' ');
        }
        printf("%d", values[i]);
    }
    putchar('\n');
}

enum { CAPACITY = 8 };

int main(void)
{
    int original[CAPACITY];
    int sorted[CAPACITY];
    int length;
    if (read_integer(0, CAPACITY, &length) != READ_OK) {
        puts("invalid");
        return 0;
    }
    if (length == 0) {
        puts("empty");
        return 0;
    }

    for (int i = 0; i < length; ++i) {
        if (read_integer(-99, 99, &original[i]) != READ_OK) {
            puts("invalid");
            return 0;
        }
    }
    for (int i = 0; i < length; ++i) {
        sorted[i] = original[i];
    }

    sort_ascending(sorted, length);
    print_row(original, length);
    print_row(sorted, length);
    return 0;
}

